window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["kubernetes-17-storage-br-persistence-br-for-pods"]={"html":"Storage — Kubernetes Book 05\n\n\n<a href=\"#toc\">▤ TOC</a>\n\n\n<div class=\"page cover\">\n<div class=\"orb\"></div>\n<div class=\"orb\"></div>\n<div class=\"wheel\">💾</div>\n<h1 id=\"storagepersistencefor-pods\">STORAGE<br />PERSISTENCE<br />FOR PODS</h1>\n<div class=\"sub\">Book 05 of the series — giving data a life of its own: Volumes, the PV/PVC divorce of supply and demand, access modes decoded (RWO ≠ one Pod!), reclaim policies, StorageClasses &amp; dynamic provisioning, StatefulSet per-replica storage, and the CSI universal plug.</div>\n<div class=\"row\">\n<div class=\"glass\">💾 Volumes<small>pod attachments</small></div>\n<div class=\"glass\">📦 PV<small>cluster supply</small></div>\n<div class=\"glass\">📝 PVC<small>the request</small></div>\n<div class=\"glass\">🔀 RWO·ROX·RWX<small>decoded</small></div>\n</div>\n<div class=\"row\">\n<div class=\"glass\">♻️ Reclaim<small>Retain · Delete</small></div>\n<div class=\"glass\">🏭 StorageClass<small>build on demand</small></div>\n<div class=\"glass\">🪪 StatefulSet<small>storage per replica</small></div>\n<div class=\"glass\">🔌 CSI<small>universal plug</small></div>\n</div>\n<div class=\"ver\">K8S KNOWLEDGE BASE · BOOK 05 · CONTINUES BOOKS 01–04 · 2026</div>\n</div>\n\n\n<div class=\"page\">\n<div class=\"pghead\"><span class=\"chip\">📖</span><h2 id=\"contents-click-any-row\">Contents — click any row</h2><span class=\"dbadge\">7 parts · 20 chapters</span></div>\n<div class=\"tocgrid\">\n<div class=\"tocpart\">Part I · The Persistence Problem</div>\n<a href=\"#ch01\"><span class=\"cb\"></span><span class=\"tnum\">CH 01</span>Why Storage Is Different<span class=\"dots\"></span><span class=\"tp\">p.3</span></a>\n<a href=\"#ch02\"><span class=\"cb\"></span><span class=\"tnum\">CH 02</span>Volumes — The Pod's Attachments<span class=\"dots\"></span><span class=\"tp\">p.4</span></a>\n<div class=\"tocpart\">Part II · PV &amp; PVC</div>\n<a href=\"#ch03\"><span class=\"cb\"></span><span class=\"tnum\">CH 03</span>PV &amp; PVC — Supply Meets Demand<span class=\"dots\"></span><span class=\"tp\">p.5</span></a>\n<a href=\"#ch04\"><span class=\"cb\"></span><span class=\"tnum\">CH 04</span>The Binding Process<span class=\"dots\"></span><span class=\"tp\">p.6</span></a>\n<a href=\"#ch05\"><span class=\"cb\"></span><span class=\"tnum\">CH 05</span>Access Modes — RWO·ROX·RWX Decoded<span class=\"dots\"></span><span class=\"tp\">p.7</span></a>\n<a href=\"#ch06\"><span class=\"cb\"></span><span class=\"tnum\">CH 06</span>Reclaim Policies &amp; the PV Lifecycle<span class=\"dots\"></span><span class=\"tp\">p.8</span></a>\n<div class=\"tocpart\">Part III · Dynamic Provisioning</div>\n<a href=\"#ch07\"><span class=\"cb\"></span><span class=\"tnum\">CH 07</span>StorageClasses — Build on Demand<span class=\"dots\"></span><span class=\"tp\">p.9</span></a>\n<a href=\"#ch07b\"><span class=\"cb\"></span><span class=\"tnum\">CH 07·b</span>StorageClasses (cont.)<span class=\"dots\"></span><span class=\"tp\">p.10</span></a>\n<a href=\"#ch08\"><span class=\"cb\"></span><span class=\"tnum\">CH 08</span>Class Tuning — Binding Modes &amp; Expansion<span class=\"dots\"></span><span class=\"tp\">p.10</span></a>\n<div class=\"tocpart\">Part IV · Stateful Storage</div>\n<a href=\"#ch09\"><span class=\"cb\"></span><span class=\"tnum\">CH 09</span>StatefulSets — Why Identity Matters<span class=\"dots\"></span><span class=\"tp\">p.11</span></a>\n<a href=\"#ch10\"><span class=\"cb\"></span><span class=\"tnum\">CH 10</span>volumeClaimTemplates — Storage Per Replica<span class=\"dots\"></span><span class=\"tp\">p.12</span></a>\n<div class=\"tocpart\">Part V · Under the Hood</div>\n<a href=\"#ch11\"><span class=\"cb\"></span><span class=\"tnum\">CH 11</span>CSI — The Universal Plug<span class=\"dots\"></span><span class=\"tp\">p.13</span></a>\n<div class=\"tocpart\">Part VI · Labs</div>\n<a href=\"#lab1\"><span class=\"cb\"></span><span class=\"tnum\">LAB 1</span>Manual PV ↔ PVC Binding<span class=\"dots\"></span><span class=\"tp\">p.14</span></a>\n<a href=\"#lab2\"><span class=\"cb\"></span><span class=\"tnum\">LAB 2</span>Dynamic Provisioning + Reclaim Proof<span class=\"dots\"></span><span class=\"tp\">p.15</span></a>\n<a href=\"#lab3\"><span class=\"cb\"></span><span class=\"tnum\">LAB 3</span>StatefulSet — Identity &amp; Per-Replica Data<span class=\"dots\"></span><span class=\"tp\">p.16</span></a>\n<a href=\"#lab3b\"><span class=\"cb\"></span><span class=\"tnum\">LAB 3·b</span>StatefulSet (cont.)<span class=\"dots\"></span><span class=\"tp\">p.17</span></a>\n<a href=\"#lab4\"><span class=\"cb\"></span><span class=\"tnum\">LAB 4</span>The Data-Survival Gauntlet<span class=\"dots\"></span><span class=\"tp\">p.17</span></a>\n<div class=\"tocpart\">Part VII · Prove It</div>\n<a href=\"#quiz\"><span class=\"cb\"></span><span class=\"tnum\">QUIZ</span>Self-Check Quiz<span class=\"dots\"></span><span class=\"tp\">p.18</span></a>\n<a href=\"#key\"><span class=\"cb\"></span><span class=\"tnum\">KEY</span>Answer Key + Scoring<span class=\"dots\"></span><span class=\"tp\">p.19</span></a>\n<a href=\"#gloss\"><span class=\"cb\"></span><span class=\"tnum\">GLOSS</span>Glossary<span class=\"dots\"></span><span class=\"tp\">p.20</span></a>\n<a href=\"#cheat\"><span class=\"cb\"></span><span class=\"tnum\">CHEAT</span>One-Page Cheat Sheet<span class=\"dots\"></span><span class=\"tp\">p.21</span></a>\n<a href=\"#finale\"><span class=\"cb\"></span><span class=\"tnum\">FINALE</span>Where to Next → Book 06<span class=\"dots\"></span><span class=\"tp\">p.22</span></a>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Assumes Books 01–04.</b> Book 01 · CH 11 already told you PVs are <b>cluster-scoped</b> — now you'll see why. Book 04 · CH 10's <code>--delete-emptydir-data</code> flag was this book knocking: <i>emptyDir dies with the Pod, and drain makes you choose</i>. Book 02's Secrets return as CSI credentials (CH 11).</div></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span>◀ cover · start ▶</span><span>Page 2</span></div>\n</div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 01</span><h2 id=\"why-storage-is-different\">🕳️ Why Storage Is Different</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<p>Everything so far assumed Pods are expendable — and their <b>filesystem is too</b>. A container's writable layer is built fresh from the image every time the container is replaced. Data written \"inside the container\" has a death wish.</p>\n<div class=\"zone\">\n<div class=\"zlabel\">The three lives of data — how long does it survive?</div>\n<div class=\"mtree\">1 · <b>Container writable layer</b>   <span class=\"r\">dies with the CONTAINER</span>\n    <span class=\"g\">crash → kubelet restarts → fresh layer → your writes GONE</span>\n2 · <b>emptyDir volume</b>              <span class=\"y\">dies with the POD</span>\n    <span class=\"g\">survives container restarts — deleted when the Pod leaves the node</span>\n3 · <b>PersistentVolumes</b>             <span class=\"p\">outlives EVERYTHING</span>\n    <span class=\"g\">pods, nodes, even the cluster's opinion — data remains</span></div>\n</div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">❌ Fine without persistence</div>\n<ul><li>Stateless APIs (state lives in a DB <i>elsewhere</i>)</li><li>Static sites, proxies, workers</li><li>Scratch space, temp files (emptyDir!)</li></ul></div>\n<div class=\"card\"><div class=\"zlabel\">💀 Dies without persistence</div>\n<ul><li>Databases (MySQL, Postgres — Book 01's YAML wrote nothing durable!)</li><li>User uploads, sessions</li><li>Message queues, ML models, indexes</li></ul></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Book 04 foreshadowed this:</b> <code>drain --delete-emptydir-data</code> exists precisely because emptyDir data dies with the Pod — drain makes you <i>admit</i> it. And Book 01's MySQL lab ran on the container layer: that database was one crash away from amnesia.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> Kubernetes treats Pods as cattle — so anything that must <b>outlive a Pod</b> needs to live <i>outside</i> the container layer, declared as a Volume at minimum and a PersistentVolume at best. This book is the ladder from scratch space to real persistence.</div></div>\n<p>⏭️ Step one of the ladder — <a href=\"#ch02\">CH 02: Volumes — The Pod's Attachments</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#toc\">▤ TOC</a> · <a href=\"#ch02\">next ▶</a></span><span>Page 3</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 02</span><h2 id=\"volumes-the-pod-s-attachments\">🎒 Volumes — The Pod's Attachments</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A Volume is a <b>directory, declared at Pod level, mounted into containers</b>. It outlives the containers in the Pod — but its lifespan depends on its <b>type</b>.</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">containers</span>:\n  - <span class=\"c\">name</span>: app\n    <span class=\"c\">image</span>: myapp:2.0\n    <span class=\"c\">volumeMounts</span>:\n    - { <span class=\"c\">name</span>: scratch, <span class=\"c\">mountPath</span>: <span class=\"m\">/tmp/cache</span> }\n  <span class=\"c\">volumes</span>:                      <span class=\"g\"># declared at POD level — shared by containers</span>\n  - <span class=\"c\">name</span>: scratch\n    <span class=\"c\">emptyDir</span>: {}</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Type</th><th>Backing</th><th>Lifespan</th><th>Use for</th></tr>\n<tr><td><code>emptyDir</code></td><td>node disk / RAM (<code>medium: Memory</code>)</td><td>Pod's life</td><td>scratch, multi-container share, checkpointing</td></tr>\n<tr><td><code>hostPath</code></td><td>a path <b>on the node</b></td><td>survives the Pod — <b>tied to the node</b></td><td>⚠️ node agents, privileged daemons only</td></tr>\n<tr><td><code>configMap</code> / <code>secret</code></td><td>API objects (Book 02 · CH 02/06)</td><td>Pod's life, kubelet-synced</td><td>config &amp; credentials as files</td></tr>\n<tr><td><code>nfs</code></td><td>an NFS share</td><td>independent of Pod</td><td>shared file storage</td></tr>\n<tr><td><code>persistentVolumeClaim</code></td><td>a PV via binding</td><td><b>independent</b> — the star ⭐</td><td>real persistence (Part II)</td></tr>\n<tr><td><code>csi</code></td><td>any CSI driver (CH 11)</td><td>driver-defined</td><td>ephemeral CSI volumes</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>hostPath is a loaded weapon:</b> it hard-couples your Pod to <i>a specific path on whatever node it lands on</i> — rescheduling to another node = \"where did my data go?\" It can also read <b>any path on the node</b> (including <code>/</code>) — a container-escape classic. Legit uses: kubelet-adjacent daemons (log shippers, CNI). Everything else: use a PVC.</div></div>\n<ul>\n<li>🤝 <b>Shared fate, shared files:</b> two containers in one Pod mounting the same Volume = the Book 01 · CH 19 sidecar pattern's backbone (the log-shipper read the app's file from one)</li>\n<li>📏 <code>emptyDir.sizeLimit</code> caps growth — beyond it, eviction (kubelet treats it like disk pressure)</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> a Volume is a <b>Pod-scoped directory</b> whose <i>backing</i> (and lifespan) is chosen by its type — from RAM-speed scratch (emptyDir) to node-coupled files (hostPath) to the fully independent PVC, which is where the rest of this book lives.</div></div>\n<p>⏭️ The star of the ladder — <a href=\"#ch03\">CH 03: PV &amp; PVC — Supply Meets Demand</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch01\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch03\">next ▶</a></span><span>Page 4</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 03</span><h2 id=\"pv-amp-pvc-supply-meets-demand\">🤝 PV &amp; PVC — Supply Meets Demand</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The genius of Kubernetes storage is a <b>divorce of concerns</b>: the people who <i>provision</i> storage (ops, storage admins) and the people who <i>consume</i> it (developers) never talk to each other. They meet through two objects.</p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">📦 PersistentVolume — the SUPPLY</div>\n<div class=\"term mini\"><span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: PersistentVolume\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: pv-warehouse-1 }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">capacity</span>:\n    <span class=\"c\">storage</span>: <span class=\"y\">5Gi</span>\n  <span class=\"c\">accessModes</span>: [<span class=\"m\">ReadWriteOnce</span>]\n  <span class=\"c\">persistentVolumeReclaimPolicy</span>: <span class=\"y\">Retain</span>\n  <span class=\"c\">hostPath</span>: { <span class=\"c\">path</span>: <span class=\"m\">/data/pv1</span> }</div>\n<p><b>Cluster-scoped</b> (Book 01 · CH 11 promised!). Real storage: NFS, cloud disk, hostPath. No namespace, owned by admins.</p></div>\n<div class=\"card\">\n<div class=\"zlabel\">📝 PersistentVolumeClaim — the DEMAND</div>\n<div class=\"term mini\"><span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: PersistentVolumeClaim\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: db-data, <span class=\"c\">namespace</span>: shop }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">resources</span>:\n    <span class=\"c\">requests</span>:\n      <span class=\"c\">storage</span>: <span class=\"y\">3Gi</span>\n  <span class=\"c\">accessModes</span>: [<span class=\"m\">ReadWriteOnce</span>]\n  <span class=\"c\">storageClassName</span>: <span class=\"m\">\"\"</span>   <span class=\"g\"># \"\" = manual binding only (CH 07)</span></div>\n<p><b>Namespaced</b>. Not storage — a <i>wish</i>: \"I need 3Gi, RWO.\" The developer's entire vocabulary of storage.</p></div>\n</div>\n<div class=\"zone zone-store\">\n<div class=\"zlabel\">The meeting — binding turns two wishes into a contract</div>\n<div class=\"rowc\">\n<div class=\"nb c-slate\">👷 Ops<small>provisions PVs</small></div>\n<span class=\"harr\">──►</span>\n<div class=\"nb c-violet\">📦 PV<small>cluster supply</small></div>\n<span class=\"harr\">⇄</span>\n<div class=\"nb c-emerald\">📝 PVC<small>ns: shop</small></div>\n<span class=\"harr\">◄──</span>\n<div class=\"nb c-slate\">👩‍💻 Dev<small>writes a claim</small></div>\n</div>\n<p>PVC bound → Pods mount the <i>claim</i>, never the volume: <code>volumes: [{name: data, persistentVolumeClaim: {claimName: db-data}}]</code></p>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>The apartment analogy, upgraded:</b> the PV is the <b>warehouse in the building's basement</b> (building-wide, managed by the landlord). The PVC is your <b>lease application</b> (\"3Gi storage, I need to write to it\"). You never touch the warehouse — you mount your <i>lease</i>.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> <i>PV = cluster-scoped real storage (supply) · PVC = namespaced request (demand) · binding = the matchmaking</i> — and Pods only ever reference the PVC, keeping consumers and infrastructure permanently decoupled.</div></div>\n<p>⏭️ How the matchmaker works — <a href=\"#ch04\">CH 04: The Binding Process</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch02\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch04\">next ▶</a></span><span>Page 5</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 04</span><h2 id=\"the-binding-process\">🔗 The Binding Process</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A controller (the <b>PV controller</b>, inside kube-controller-manager) continuously matches Pending claims to Available volumes. Four checks, all must pass:</p>\n<div class=\"zone zone-cp\">\n<div class=\"zlabel\">The matcher's four questions</div>\n<div class=\"rowc\">\n<div class=\"kchip\">1 · Capacity<small> PV ≥ request?</small></div>\n<div class=\"kchip\">2 · Access modes<small> PV ⊇ requested?</small></div>\n<div class=\"kchip\">3 · storageClassName<small> exact match?</small></div>\n<div class=\"kchip\">4 · selector<small> labels match?</small></div>\n</div>\n<p>smallest PV that fits wins · binding is 1:1 — a bound PV is spoken for</p>\n</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Check</th><th>Rule</th><th>Gotcha</th></tr>\n<tr><td><b>Capacity</b></td><td>PV's <code>storage</code> ≥ PVC's request</td><td>you get the <i>whole</i> PV, not a slice — a 3Gi claim on a 5Gi PV wastes 2Gi</td></tr>\n<tr><td><b>Access modes</b></td><td>PV offers <i>at least</i> what the claim asks</td><td>claim <code>[RWO]</code> can bind a PV offering <code>[RWO, RWX]</code></td></tr>\n<tr><td><b>StorageClass</b></td><td><b>exact string match</b> — including <code>\"\"</code></td><td>claim with <code>className: \"\"</code> binds <i>only</i> PVs also stamped <code>\"\"</code>; a claim with <i>no</i> field uses the default class (CH 07)</td></tr>\n<tr><td><b>Selector</b></td><td>claim's <code>selector.matchLabels</code> ⊆ PV labels</td><td>ops tags PVs (<code>tier: gold</code>), devs target the tag</td></tr>\n</table></div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get pvc db-data\n<span class=\"y\">NAME     STATUS   VOLUME         CAPACITY  ACCESS MODES</span>\ndb-data  <span class=\"r\">Pending</span>                    <span class=\"g\"># nobody fits — check the 4 questions</span>\ndb-data  <span class=\"p\">Bound</span>    pv-warehouse-1  5Gi       RWO</div>\n<ul>\n<li>🎯 <b>Pre-binding:</b> a PV can name its soulmate in <code>spec.claimRef</code> — skips the matchmaking entirely (migrations, DR drills)</li>\n<li>🔒 <b>Binding is exclusive:</b> one PV ↔ one PVC, period. Sharing storage between Pods happens <i>through the same claim</i>, not through multiple bindings</li>\n</ul>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Pending PVC triage:</b> 90% of stuck claims are the <b>storageClassName mismatch</b> — claim says <code>\"\"</code> but only classed PVs exist, or vice versa. The other 10%: capacity too small, access-mode subset missing, or selector pointing at labels nobody has.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> binding = <i>capacity ≥, modes ⊇, class ==, labels match — smallest fitting PV wins, exactly one claim per PV</i>. Every Pending PVC is one of those four questions answered wrong.</div></div>\n<p>⏭️ The matching criterion with the most lies attached — <a href=\"#ch05\">CH 05: Access Modes Decoded</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch03\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch05\">next ▶</a></span><span>Page 6</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 05</span><h2 id=\"access-modes-rwo-rox-rwx-decoded\">🔀 Access Modes — RWO·ROX·RWX Decoded</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The names are honest about read/write but <b>lying about the unit</b>. The unit is <b>NODES</b>, not Pods — and that one fact explains half of all storage tickets.</p>\n<div class=\"table-scroll\"><table>\n<tr><th>Mode</th><th>Name says</th><th><b>Really means</b></th><th>Typical backing</th></tr>\n<tr><td><code>ReadWriteOnce</code></td><td>one writer</td><td>read-write mounted by <b>ONE NODE</b></td><td>cloud block disks: EBS, PD, Azure Disk</td></tr>\n<tr><td><code>ReadOnlyMany</code></td><td>many readers</td><td>read-only on <b>MANY nodes</b></td><td>NFS, EFS (ro), pre-staged datasets</td></tr>\n<tr><td><code>ReadWriteMany</code></td><td>shared write</td><td>read-write on <b>MANY nodes</b></td><td>NFS, EFS, Azure Files, CephFS</td></tr>\n<tr><td><code>ReadWriteOncePod</code> <span class=\"stbadge st-comp\">newer</span></td><td>one writer</td><td>read-write by <b>ONE POD</b> — truly exclusive (GA 1.29)</td><td>block disks, with the strictest semantics</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The interview trap:</b> <b>RWO ≠ one Pod.</b> It's one <i>node</i> — so <b>three Pods on the same node can all mount one RWO volume simultaneously</b>, while the same three Pods spread across three nodes cannot. When your scaled Deployment mysteriously wedges, this is why: replicas scattered across nodes fight over one RWO claim.</div></div>\n<div class=\"zone zone-store\">\n<div class=\"zlabel\">Multi-Attach — the classic failure</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl describe pod db-2 | tail -2\n  <span class=\"y\">Events:</span>\n<span class=\"r\">  Multi-Attach error for volume \"pvc-abc\":\n  Volume is already exclusively attached to one node\n  and can't be attached to another</span>\n<span class=\"g\"># Pod B (other node) wants the RWO volume Pod A's node holds.\n# The volume driver physically can't attach a block disk twice.</span></div>\n</div>\n<ul>\n<li>🧱 <b>Block storage = RWO-only:</b> a cloud disk plugs into one machine — RWX demands a <i>shared filesystem</i> (NFS/EFS/Ceph) or an in-cluster one (NFS provisioner, Longhorn, EFS CSI)</li>\n<li>🔍 <b>Check reality, not hopes:</b> <code>kubectl get pv</code> shows the PV's ACCESS MODES — a claim asking RWX will sit <b>Pending forever</b> against an RWO-only fleet</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> access modes are promises about <b>node-level attach</b> — RWO = one node (not one Pod!), RWX = needs genuinely shared backing — and <code>Multi-Attach error</code> in events is the sound of a block disk refusing to be in two places at once.</div></div>\n<p>⏭️ What happens when the love ends — <a href=\"#ch06\">CH 06: Reclaim Policies</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch04\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch06\">next ▶</a></span><span>Page 7</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 06</span><h2 id=\"reclaim-policies-amp-the-pv-lifecycle\">♻️ Reclaim Policies &amp; the PV Lifecycle</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A PV has a whole life <i>after</i> its claim dies. The <b>reclaim policy</b> decides what that afterlife looks like — and whether your data survives it.</p>\n<div class=\"mtree\"><b>Available</b> <span class=\"g\">→</span> <b>Bound</b> <span class=\"g\">→ PVC deleted →</span> <b>Released</b> <span class=\"g\">→ policy decides →</span>\n      │                                              │\n<span class=\"u\">Retain:</span>  stays <b>Released</b> forever — data intact, <span class=\"y\">ADMIN must intervene</span>\n<span class=\"u\">Delete:</span>  PV object + <b>backing storage</b> both destroyed  <span class=\"g\">← dynamic default</span>\n<span class=\"u\">Recycle:</span> <s>scrub &amp; re-offer</s> — <b>REMOVED</b> from the API (dynamic provisioning replaced it)</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Policy</th><th>PVC deleted →</th><th>Data</th><th>Use when</th></tr>\n<tr><td><span class=\"stbadge st-comp\">Retain</span></td><td>PV → <b>Released</b>, never auto-reused</td><td><span class=\"ok\">kept</span> — hostage until an admin acts</td><td>databases, anything you'd cry over</td></tr>\n<tr><td><span class=\"stbadge st-run\">Delete</span></td><td>PV + cloud disk <b>annihilated</b></td><td><span class=\"bad\">gone</span></td><td>truly ephemeral state, CI scratch</td></tr>\n</table></div>\n<div class=\"term mini\"><span class=\"g\"># the Released hostage situation — and the escape:</span>\n<span class=\"p\">$</span> kubectl get pv\n<span class=\"y\">NAME    CAPACITY  CLAIM             RECLAIM  STATUS</span>\npv-db   5Gi       shop/db-data     Retain   <span class=\"r\">Released</span>\n<span class=\"g\"># reuse it manually: clear the claimRef → back to Available\n# (data intact! next binding re-attaches the same disk)</span>\n<span class=\"p\">$</span> kubectl patch pv pv-db <span class=\"y\">-p</span> <span class=\"m\">'{\"spec\":{\"claimRef\": null}}'</span></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Two honest warnings:</b> (1) the <b>pvc-protection finalizer</b> — a PVC in use by a Pod shows <span class=\"stbadge st-term\">Terminating</span> indefinitely; Kubernetes refuses to yank storage from a running Pod. (2) <b>Default is Delete for dynamic volumes</b> — an innocent <code>kubectl delete pvc</code> on a Delete-class volume is a production data-loss event. Patch the PV (or the class, CH 08) to <code>Retain</code> for anything real.</div></div>\n<ul>\n<li>🔁 <b>Released ≠ Available:</b> Released PVs are NOT re-matchable — that's the point of Retain (no accidental rebinding of dirty state)</li>\n<li>🧾 <b>Audit trick:</b> <code>kubectl get pv -o custom-columns=NAME:.metadata.name,POLICY:.spec.persistentVolumeReclaimPolicy,STATUS:.status.phase</code> — one glance, whole estate</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> the PV lifecycle is <i>Available → Bound → Released → {Retain: wait for admin | Delete: erase everything}</i> — and the difference between \"I deleted a claim\" and \"I deleted the company's data\" is one policy field.</div></div>\n<p>⏭️ What if you never write a PV at all? — <a href=\"#ch07\">CH 07: StorageClasses</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch05\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch07\">next ▶</a></span><span>Page 8</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 07</span><h2 id=\"storageclasses-build-on-demand\">🏭 StorageClasses — Build on Demand</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Writing PVs by hand doesn't scale — it's the landlord hand-building a warehouse per lease. A <b>StorageClass</b> is the <b>construction company</b>: PVCs name it, and it builds the warehouse automatically.</p>\n<div class=\"term\"><span class=\"c\">apiVersion</span>: storage.k8s.io/v1\n<span class=\"c\">kind</span>: StorageClass\n<span class=\"c\">metadata</span>:\n  <span class=\"c\">name</span>: fast\n  <span class=\"c\">annotations</span>:\n    <span class=\"y\">storageclass.kubernetes.io/is-default-class</span>: <span class=\"m\">\"true\"</span>  <span class=\"g\"># THE default</span>\n<span class=\"c\">provisioner</span>: <span class=\"m\">ebs.csi.aws.com</span>      <span class=\"g\"># WHO builds (CSI driver — CH 11)</span>\n<span class=\"c\">parameters</span>:                        <span class=\"g\"># the build spec, vendor-specific</span>\n  <span class=\"c\">type</span>: <span class=\"m\">gp3</span>\n  <span class=\"c\">encrypted</span>: <span class=\"m\">\"true\"</span>\n<span class=\"c\">reclaimPolicy</span>: <span class=\"y\">Delete</span>             <span class=\"g\"># default for dynamic volumes</span>\n<span class=\"c\">allowVolumeExpansion</span>: <span class=\"y\">true</span>        <span class=\"g\"># grow later (CH 08)</span>\n<span class=\"c\">volumeBindingMode</span>: <span class=\"y\">WaitForFirstConsumer</span>  <span class=\"g\"># smart timing (CH 08)</span></div>\n<div class=\"zone zone-store\">\n<div class=\"zlabel\">Dynamic provisioning — the whole dance, automated</div>\n<div class=\"rowc\">\n<div class=\"kchip\">📝 PVC<small>className: fast</small></div><span class=\"harr\">──►</span>\n<div class=\"nb c-violet\">🏭 SC<small>\"fast\"</small></div><span class=\"harr\">──►</span>\n<div class=\"nb c-indigo\">🔌 Provisioner<small>CSI driver</small></div>\n</div>\n<div class=\"dn\">▼ builds real storage (EBS volume etc.)</div>\n<div class=\"rowc\">\n<div class=\"nb c-slate\">📦 PV auto-created<small>cap · modes · policy</small></div><span class=\"harr\">──►</span>\n<div class=\"nb c-emerald\">📝 PVC<small>Bound ✓</small></div><span class=\"harr\">──►</span>\n<div class=\"pod\">🫛 Pod mounts it</div>\n</div>\n<p>zero PVs hand-written · the SC name in the claim is the only thing a developer must know</p>\n</div>\n<div class=\"table-scroll\"><table>\n<tr><th>PVC's storageClassName</th><th>Result</th></tr>\n<tr><td>names a class (<code>fast</code>)</td><td>dynamic provisioning <b>from that class</b> — manual PVs of the same name are bypassed unless matching perfectly</td></tr>\n<tr><td><i>field omitted</i> + a default class exists</td><td>uses the <b>default class</b> — <code>standard</code> on minikube/kind</td></tr>\n<tr><td><i>field omitted</i> + <b>no</b> default</td><td>old-school manual binding only — usually <span class=\"bad\">Pending forever</span></td></tr>\n<tr><td><code>\"\"</code> (empty string)</td><td><b>explicitly opts OUT</b> of dynamic — manual PVs only (CH 04's matcher)</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Classes are also a menu:</b> <code>fast</code> (NVMe), <code>cheap</code> (HDD), <code>shared</code> (NFS/RWX) — the same cluster offers different storage <i>tiers</i>, and the developer picks by writing one name. Multi-cloud? One class per backend, one field per claim.</div></div>\n\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch06\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch08\">next ▶</a></span><span>Page 9</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 07</span><h2 id=\"storageclasses-continued\">🏭 StorageClasses — continued</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> a StorageClass is a <b>named recipe — provisioner + parameters + policy — that builds PVs on demand</b>; claims name the recipe, the default class catches the lazy, and <code>\"\"</code> is the explicit \"I brought my own warehouse.\"</div></div>\n<p>⏭️ The two settings that separate toy classes from production ones — <a href=\"#ch08\">CH 08: Class Tuning</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch07\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch08\">next ▶</a></span><span>Page 10</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 08</span><h2 id=\"class-tuning-binding-modes-amp-expansion\">⚙️ Class Tuning — Binding Modes &amp; Expansion</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<h3 id=\"volumebindingmode-when-to-bind\">⏱️ volumeBindingMode — WHEN to bind</h3>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">Immediate (default)</div>\n<p>Bind the instant the PVC exists — <b>before any Pod exists</b>. Simple, but with zoned storage the disk may be born in <b>zone A while your Pod later schedules to zone C</b> → attach impossible → Pod wedged.</p>\n<div class=\"term mini\"><span class=\"r\">0/1 nodes available:\nvolume node affinity conflict</span> <span class=\"g\"># ← this error = bound to the wrong zone</span></div></div>\n<div class=\"card\">\n<div class=\"zlabel\">WaitForFirstConsumer ✅</div>\n<p>The PVC waits in <span class=\"stbadge st-pend\">Pending</span> until a <b>Pod that uses it is scheduled</b> — then provisions the disk <b>in the Pod's zone</b>. Topology-correct by construction. Production default for zoned clouds.</p>\n<div class=\"term mini\"><span class=\"g\"># PVC waits… pod schedules to zone-c…\n# disk born IN zone-c — attach just works</span></div></div>\n</div>\n<h3 id=\"allowvolumeexpansion-grow-never-shrink\">📈 allowVolumeExpansion — grow, never shrink</h3>\n<div class=\"term mini\"><span class=\"c\"># class must allow it (CH 07)… then just edit the claim:</span>\n<span class=\"p\">$</span> kubectl patch pvc db-data <span class=\"y\">-p</span> <span class=\"m\">'{\"spec\":{\"resources\":{\"requests\":{\"storage\":\"10Gi\"}}}}'</span>\n<span class=\"p\">$</span> kubectl get pvc db-data\n<span class=\"y\">NAME     CAPACITY  STATUS</span>\ndb-data  10Gi      <span class=\"p\">Bound</span>  <span class=\"g\"># filesystem resized online (most drivers)</span>\n<span class=\"g\"># SHRINKING IS IMPOSSIBLE — storage can only ever grow. plan headroom.</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Setting</th><th>Recommended</th><th>Why</th></tr>\n<tr><td><code>volumeBindingMode</code></td><td><b>WaitForFirstConsumer</b> (zoned clouds)</td><td>disk and Pod land in the same zone, always</td></tr>\n<tr><td><code>allowVolumeExpansion</code></td><td><b>true</b></td><td>DBs outgrow their bids; growing online beats migrating</td></tr>\n<tr><td><code>reclaimPolicy</code></td><td><b>Retain</b> for real data classes</td><td>CH 06: default Delete is a loaded foot-gun</td></tr>\n<tr><td><code>parameters</code></td><td>vendor-specific (<code>type: gp3</code>…)</td><td>the tier definition itself</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Debugging zoned wedges:</b> the PV inherits the zone as a <b>nodeAffinity</b> (<code>kubectl describe pv</code> → <code>Node Affinity</code> section) — the Scheduler literally cannot place Pods elsewhere. Wrong-zone = delete PVC + Pod, recreate with WaitForFirstConsumer. (Topologies from Book 04 · CH 08 pay off here.)</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> production classes set <b>WaitForFirstConsumer</b> (zone-correct disks), <b>allowVolumeExpansion: true</b> (grow-only flexibility), and <b>Retain</b> for anything with a pulse — Immediate binding on zoned storage is how disks get born in the wrong ZIP code.</div></div>\n<p>⏭️ Now the workload that truly needs all this — <a href=\"#ch09\">CH 09: StatefulSets</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch07\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch09\">next ▶</a></span><span>Page 10</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 09</span><h2 id=\"statefulsets-why-identity-matters\">🪪 StatefulSets — Why Identity Matters</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A Deployment's Pods are <b>interchangeable cattle</b> — random names, any replica can serve any request. Databases are <b>not cattle</b>: replica 0 is the primary, replica 1 is its follower, and each owns <i>its own</i> data. Enter the StatefulSet.</p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">🐄 Deployment identity</div>\n<div class=\"mtree\">web-<em>7d9f-x7k2p</em>  <span class=\"g\">random</span>\nweb-<em>7d9f-bbbba</em>  <span class=\"g\">random</span>\n<span class=\"g\">die → replaced by NEW random names\nany pod can serve anything\nno \"which one owns the data?\"</span></div></div>\n<div class=\"card\">\n<div class=\"zlabel\">🐕 StatefulSet identity</div>\n<div class=\"mtree\">db-<b>0</b>  <span class=\"g\">PRIMARY — born first</span>\ndb-<b>1</b>  <span class=\"g\">follower — waits for 0</span>\ndb-<b>2</b>  <span class=\"g\">follower — waits for 1</span>\n<span class=\"g\">die → RESURRECTED WITH THE SAME NAME\n+ same storage (CH 10) + same DNS</span></div></div>\n</div>\n<h3 id=\"the-headless-service-per-pod-dns\">📮 The headless service — per-Pod DNS</h3>\n<div class=\"term mini\"><span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: Service\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: db }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">clusterIP</span>: <span class=\"y\">None</span>            <span class=\"g\"># HEADLESS — no VIP, no balancing</span>\n  <span class=\"c\">selector</span>: { <span class=\"c\">app</span>: db }\n  <span class=\"c\">ports</span>: [{ <span class=\"c\">port</span>: <span class=\"y\">5432</span> }]\n<span class=\"g\"># instead of one VIP, DNS returns EACH POD's address:</span>\n<span class=\"g\">#   db-0.db.shop.svc.cluster.local → db-0's IP  (the primary!)</span>\n<span class=\"g\">#   followers find the primary BY NAME — no IPs in any config</span></div>\n<ul>\n<li>🔢 <b>Ordered by default:</b> 0 → Ready → then 1 → Ready → then 2; deletion runs in reverse (2 → 1 → 0). The bootstrap sequence a database needs, built in</li>\n<li>🏷️ <b>Name = contract:</b> replication configs say \"follow <code>db-0</code>\" — and it's true forever, across rescheduling and crashes</li>\n</ul>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Scope note:</b> this chapter covers identity + storage — the <i>reason</i> StatefulSets exist for data. The full lifecycle (rolling updates, <code>partition</code> canaries, OnDelete) is Book 06's territory.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> StatefulSets give each replica a <b>stable name, stable DNS, and ordered startup</b> — the preconditions for \"replica 0 owns the data\" to mean anything; next chapter attaches the storage that makes the promise complete.</div></div>\n<p>⏭️ The storage half of the contract — <a href=\"#ch10\">CH 10: volumeClaimTemplates</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch08\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch10\">next ▶</a></span><span>Page 11</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 10</span><h2 id=\"volumeclaimtemplates-storage-per-replica\">🗄️ volumeClaimTemplates — Storage Per Replica</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The StatefulSet's killer storage feature: instead of one shared claim, you embed a <b>template</b> — and each replica gets its <b>own PVC stamped from it</b>, named after the Pod it belongs to.</p>\n<div class=\"term\"><span class=\"c\">apiVersion</span>: apps/v1\n<span class=\"c\">kind</span>: StatefulSet\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: db }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">serviceName</span>: db               <span class=\"g\"># the headless service (CH 09)</span>\n  <span class=\"c\">replicas</span>: <span class=\"y\">3</span>\n  <span class=\"c\">selector</span>: { <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: db } }\n  <span class=\"c\">template</span>:                      <span class=\"g\"># the pod stamp</span>\n    <span class=\"c\">metadata</span>: { <span class=\"c\">labels</span>: { <span class=\"c\">app</span>: db } }\n    <span class=\"c\">spec</span>:\n      <span class=\"c\">containers</span>:\n      - <span class=\"c\">name</span>: db\n        <span class=\"c\">image</span>: postgres:16\n        <span class=\"c\">volumeMounts</span>:\n        - { <span class=\"c\">name</span>: data, <span class=\"c\">mountPath</span>: <span class=\"m\">/var/lib/postgresql/data</span> }\n  <span class=\"c\">volumeClaimTemplates</span>:          <span class=\"g\"># ★ THE COOKIE CUTTER FOR CLAIMS</span>\n  - <span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: data }\n    <span class=\"c\">spec</span>:\n      <span class=\"c\">accessModes</span>: [<span class=\"m\">ReadWriteOnce</span>]\n      <span class=\"c\">resources</span>: { <span class=\"c\">requests</span>: { <span class=\"c\">storage</span>: <span class=\"y\">10Gi</span> } }\n      <span class=\"c\">storageClassName</span>: fast</div>\n<div class=\"mtree\"><b>StatefulSet db (replicas: 3)</b>\n├── pod <u>db-0</u>  ⇄ PVC <u>data-db-0</u> ⇄ PV (own disk)\n├── pod <u>db-1</u>  ⇄ PVC <u>data-db-1</u> ⇄ PV (own disk)\n└── pod <u>db-2</u>  ⇄ PVC <u>data-db-2</u> ⇄ PV (own disk)\n<span class=\"g\">naming law:  &lt;template-name&gt;-&lt;statefulset&gt;-&lt;ordinal&gt;</span></div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">✅ Scale UP → claims born</div>\n<p>3 → 4 replicas: <code>data-db-3</code> dynamically provisioned (CH 07!), mounted by <code>db-3</code>. Fresh disk, zero setup.</p></div>\n<div class=\"card\"><div class=\"zlabel\">⚠️ Scale DOWN → claims RETAINED</div>\n<p>4 → 2: Pods <code>db-3</code>, <code>db-2</code> die — but <b>their PVCs stay</b> (data-safety by design). Scale back up and the same replicas <b>reunite with their old disks</b>.</p></div>\n</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Deleting the StatefulSet deletes NOTHING storage-wise</b> — every <code>data-db-N</code> survives (Retain-like behavior, baked in). Cleanup is manual: <code>kubectl delete pvc data-db-0 data-db-1 …</code> This is the storage counterpart of Book 01's cascade lesson — <i>some deletes cascade (namespaces), some deliberately don't (STS claims)</i>.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> <code>volumeClaimTemplates</code> = <b>one PVC per replica, named for its Pod, born on scale-up, kept on scale-down</b> — the mechanism that lets <code>db-0</code> mean \"the primary <i>and its exact disk</i>\" forever.</div></div>\n<p>⏭️ Who builds the disks behind it all — <a href=\"#ch11\">CH 11: CSI</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch09\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch11\">next ▶</a></span><span>Page 12</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 11</span><h2 id=\"csi-the-universal-plug\">🔌 CSI — The Universal Plug</h2><span class=\"dbadge\">🟡 5 MIN</span></div>\n<p>Every provisioner you've met (<code>ebs.csi.aws.com</code>, minikube's <code>hostpath</code>, Ceph…) speaks <b>CSI — the Container Storage Interface</b>: a vendor-neutral gRPC contract that lets <i>any</i> storage backend plug into <i>any</i> Kubernetes.</p>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">🏺 Before CSI (in-tree era)</div>\n<ul><li>Driver code lived <b>inside the k8s source tree</b></li><li>Vendors begged SIGs for inclusion; releases tied to k8s cycles</li><li>k8s shipped hundreds of drivers it couldn't all test</li></ul></div>\n<div class=\"card\"><div class=\"zlabel\">🔌 After CSI</div>\n<ul><li>Drivers are <b>containers you install</b> (Helm charts)</li><li>Vendors release on <b>their</b> schedule, any k8s version</li><li>In-tree drivers: <b>frozen &amp; deprecated</b> — CSI is the only growth path</li></ul></div>\n</div>\n<div class=\"mtree\"><b>Pod</b> ⇄ <u>PVC</u> ⇄ <u>StorageClass.provisioner</u> = <b>\"ebs.csi.aws.com\"</b>\n        │\n        ▼\n<b>CSI driver</b> — two halves, both just Pods:\n├── <u>Controller plugin</u> <span class=\"g\">(Deployment)</span> — CreateVolume, DeleteVolume, Expand\n└── <u>Node plugin</u>      <span class=\"g\">(DaemonSet — one per node, Book 04 CH 10 skips these!)</span>\n     └── NodeStageVolume / NodePublishVolume → the disk appears at the mountPath</div>\n<ul>\n<li>🔐 <b>Credentials, of course, are Secrets</b> (Book 02 · CH 05–06): the driver's chart consumes a Secret holding cloud API keys / backend tokens</li>\n<li>🧩 <b>volumeMode:</b> <code>Filesystem</code> (default — a formatted dir) vs <code>Block</code> (raw device handed to the Pod — databases that manage their own formatting love it)</li>\n<li>🌍 Examples in the wild: <code>ebs.csi.aws.com</code> · <code>pd.csi.storage.gke.io</code> · <code>disk.csi.azure.com</code> · <code>rbd.csi.ceph.com</code> · <code>driver.longhorn.io</code></li>\n</ul>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Reading a class like a pro:</b> the <code>provisioner</code> field is a CSI driver identity. If a class says <code>kubernetes.io/aws-ebs</code> (old in-tree name) on a modern cluster — that's a legacy class on migration watch.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence:</b> CSI is the <b>USB standard of storage</b> — a stable plug spec that turned storage drivers from kernel-adjacent k8s features into ordinary installable containers, which is why every class you'll ever write ends in a <code>…csi…</code> provisioner.</div></div>\n<p>⏭️ Prove all of it with your hands — <a href=\"#lab1\">Part VI: Labs</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch10\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab1\">labs ▶</a></span><span>Page 13</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 1</span><h2 id=\"manual-pv-pvc-binding\">🔬 Manual PV ↔ PVC Binding</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Provision supply by hand</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl apply -f - <span class=\"c\">&lt;&lt;EOF</span>\n<span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: PersistentVolume\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: pv-manual-1, <span class=\"c\">labels</span>: { <span class=\"c\">tier</span>: lab } }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">capacity</span>: { <span class=\"c\">storage</span>: <span class=\"y\">1Gi</span> }\n  <span class=\"c\">accessModes</span>: [<span class=\"m\">ReadWriteOnce</span>]\n  <span class=\"c\">persistentVolumeReclaimPolicy</span>: <span class=\"y\">Retain</span>\n  <span class=\"c\">storageClassName</span>: <span class=\"m\">\"\"</span>\n  <span class=\"c\">hostPath</span>: { <span class=\"c\">path</span>: <span class=\"m\">/data/pv-manual-1</span>, <span class=\"c\">type</span>: <span class=\"y\">DirectoryOrCreate</span> }\n<span class=\"c\">EOF</span>\n<span class=\"p\">$</span> kubectl get pv pv-manual-1  <span class=\"g\"># STATUS: Available (2 of the 4 checks pre-passed)</span></div></div>\n<div class=\"labstep\"><div>STEP 2 · Demand + consume</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl apply -f - <span class=\"c\">&lt;&lt;EOF</span>\n<span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: PersistentVolumeClaim\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: lab-claim }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">accessModes</span>: [<span class=\"m\">ReadWriteOnce</span>]\n  <span class=\"c\">resources</span>: { <span class=\"c\">requests</span>: { <span class=\"c\">storage</span>: <span class=\"y\">500Mi</span> } }\n  <span class=\"c\">storageClassName</span>: <span class=\"m\">\"\"</span>          <span class=\"g\"># match the PV's \"\" — CH 04 rule 3</span>\n  <span class=\"c\">selector</span>: { <span class=\"c\">matchLabels</span>: { <span class=\"c\">tier</span>: lab } }\n<span class=\"c\">EOF</span>\n<span class=\"p\">$</span> kubectl get pvc lab-claim   <span class=\"g\"># Bound → pv-manual-1 (smallest fitting PV)</span>\n<span class=\"p\">$</span> kubectl run writer --image=busybox:1.36 --restart=Never --rm -it \\\n  --overrides=<span class=\"m\">'{\"spec\":{\"containers\":[{\"name\":\"w\",\"image\":\"busybox:1.36\",\n  \"command\":[\"sh\",\"-c\",\"echo persistent rocks &gt; /data/hello.txt; sleep 5\"],\n  \"volumeMounts\":[{\"name\":\"d\",\"mountPath\":\"/data\"}]}],\n  \"volumes\":[{\"name\":\"d\",\"persistentVolumeClaim\":{\"claimName\":\"lab-claim\"}}]}}'</span></div></div>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 PROVE IT'S THE WAREHOUSE</div><div class=\"tabbody\"><span class=\"p\">$</span> minikube ssh \"cat /data/pv-manual-1/hello.txt\"\n<span class=\"p\">persistent rocks</span>\n<span class=\"g\"># the file lives on the NODE's disk,\n# inside the PV's hostPath —\n# not in any container</span></div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">🔍 THE 4 CHECKS, VERIFIED</div><div class=\"tabbody\"><span class=\"g\">capacity:  1Gi ≥ 500Mi  ✓\nmodes:     RWO ⊇ RWO    ✓\nclass:     \"\" == \"\"     ✓\nselector:  tier=lab     ✓\n→ smallest-fitting win, 1:1 bound</span></div></div>\n</div>\n<p><b>Teardown:</b> <code>kubectl delete pvc lab-claim</code> → PV goes <span class=\"stbadge st-term\">Released</span> (Retain! CH 06) → <code>kubectl delete pv pv-manual-1</code>.</p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#ch11\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab2\">next ▶</a></span><span>Page 14</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 2</span><h2 id=\"dynamic-provisioning-reclaim-proof\">🏭 Dynamic Provisioning + Reclaim Proof</h2><span class=\"dbadge\">🟠 10 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Zero PVs — just a claim</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get storageclass\n<span class=\"y\">NAME       PROVISIONER              RECLAIMPOLICY  BINDINGMODE</span>\nstandard  k8s.io/minikube-hostpath <span class=\"r\">Delete</span>        Immediate  <span class=\"g\"># default ✓</span>\n<span class=\"p\">$</span> kubectl apply -f - <span class=\"c\">&lt;&lt;EOF</span>\n<span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: PersistentVolumeClaim\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: dyn-claim }   <span class=\"g\"># no className → default class (CH 07)</span>\n<span class=\"c\">spec</span>:\n  <span class=\"c\">accessModes</span>: [<span class=\"m\">ReadWriteOnce</span>]\n  <span class=\"c\">resources</span>: { <span class=\"c\">requests</span>: { <span class=\"c\">storage</span>: <span class=\"y\">1Gi</span> } }\n<span class=\"c\">EOF</span>\n<span class=\"p\">$</span> kubectl get pvc dyn-claim  <span class=\"g\"># Bound — and NOBODY wrote a PV:</span>\n<span class=\"p\">$</span> kubectl get pv | <span class=\"c\">grep</span> dyn-claim  <span class=\"g\"># pvc-xxxx… auto-created by the provisioner!</span></div></div>\n<div class=\"labstep\"><div>STEP 2 · Feel the Delete policy bite</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl patch pv <span class=\"y\">&lt;auto-pv-name&gt;</span> \\\n  <span class=\"y\">-p</span> <span class=\"m\">'{\"spec\":{\"persistentVolumeReclaimPolicy\":\"Retain\"}}'</span> <span class=\"g\"># arm the trap first</span>\n<span class=\"p\">$</span> kubectl delete pvc dyn-claim\n<span class=\"p\">$</span> kubectl get pv <span class=\"y\">&lt;auto-pv-name&gt;</span>\n<span class=\"y\">STATUS</span>\n<span class=\"r\">Released</span>  <span class=\"g\"># Retain: data held hostage (CH 06) — admin must clear claimRef or delete</span>\n<span class=\"g\"># WITHOUT the patch: PV + backing storage would be GONE. Delete is the default.</span></div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Proved:</b> dynamic provisioning needs <b>zero PV authorship</b> — and the default Delete policy is one <code>delete pvc</code> away from data annihilation unless you Retain first.</div></div>\n<p><b>Teardown:</b> <code>kubectl delete pv &lt;auto-pv-name&gt;</code></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#lab1\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab3\">next ▶</a></span><span>Page 15</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 3</span><h2 id=\"statefulset-identity-amp-per-replica-data\">🔬 StatefulSet — Identity &amp; Per-Replica Data</h2><span class=\"dbadge\">🟠 15 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Headless service + StatefulSet with a claim template</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl apply -f - <span class=\"c\">&lt;&lt;EOF</span>\n<span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: Service\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: web }\n<span class=\"c\">spec</span>: { <span class=\"c\">clusterIP</span>: <span class=\"y\">None</span>, <span class=\"c\">selector</span>: { <span class=\"c\">app</span>: webs }, <span class=\"c\">ports</span>: [{ <span class=\"c\">port</span>: <span class=\"y\">80</span> }] }\n---\n<span class=\"c\">apiVersion</span>: apps/v1\n<span class=\"c\">kind</span>: StatefulSet\n<span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: web }\n<span class=\"c\">spec</span>:\n  <span class=\"c\">serviceName</span>: web\n  <span class=\"c\">replicas</span>: <span class=\"y\">2</span>\n  <span class=\"c\">selector</span>: { <span class=\"c\">matchLabels</span>: { <span class=\"c\">app</span>: webs } }\n  <span class=\"c\">template</span>:\n    <span class=\"c\">metadata</span>: { <span class=\"c\">labels</span>: { <span class=\"c\">app</span>: webs } }\n    <span class=\"c\">spec</span>:\n      <span class=\"c\">containers</span>:\n      - <span class=\"c\">name</span>: nginx\n        <span class=\"c\">image</span>: nginx:1.25\n        <span class=\"c\">volumeMounts</span>: [{ <span class=\"c\">name</span>: data, <span class=\"c\">mountPath</span>: <span class=\"m\">/usr/share/nginx/html</span> }]\n  <span class=\"c\">volumeClaimTemplates</span>:\n  - <span class=\"c\">metadata</span>: { <span class=\"c\">name</span>: data }\n    <span class=\"c\">spec</span>: { <span class=\"c\">accessModes</span>: [<span class=\"m\">ReadWriteOnce</span>],\n            <span class=\"c\">resources</span>: { <span class=\"c\">requests</span>: { <span class=\"c\">storage</span>: <span class=\"y\">100Mi</span> } } }\n<span class=\"c\">EOF</span>\n<span class=\"p\">$</span> kubectl get pods -w  <span class=\"g\"># web-0 Running → THEN web-1 (ordered! CH 09)</span></div></div>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 IDENTITY + STORAGE</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl get pvc\n<span class=\"y\">NAME       STATUS  CAPACITY</span>\n<span class=\"p\">data-web-0</span>  Bound   100Mi  <span class=\"g\">← per replica!</span>\n<span class=\"p\">data-web-1</span>  Bound   100Mi\n<span class=\"p\">$</span> kubectl run d --rm -it --image=busybox:1.36 \\\n  --restart=Never -- wget -qO- web-0.web\n<span class=\"g\"># per-pod DNS via the HEADLESS svc (CH 09)</span></div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">⚙️ WRITE PER-REPLICA DATA</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl exec web-0 -- sh -c \\\n  <span class=\"m\">'echo i-am-zero &gt; /usr/share/nginx/html/i.txt'</span>\n<span class=\"p\">$</span> kubectl exec web-1 -- sh -c \\\n  <span class=\"m\">'echo i-am-one &gt; /usr/share/nginx/html/i.txt'</span>\n<span class=\"g\"># each wrote to ITS OWN disk</span></div></div>\n</div>\n\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#lab2\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab4\">next ▶</a></span><span>Page 16</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 3</span><h2 id=\"statefulset-continued\">🔬 StatefulSet — continued</h2><span class=\"dbadge\">🟠 15 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 2 · Kill web-0 — resurrection, not reincarnation</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl delete pod web-0\n<span class=\"p\">$</span> kubectl get pod web-0  <span class=\"g\"># SAME NAME, back after reschedule</span>\n<span class=\"p\">$</span> kubectl exec web-0 -- cat /usr/share/nginx/html/i.txt\n<span class=\"p\">i-am-zero</span>  <span class=\"g\"># ← its OWN data survived: data-web-0 reattached</span></div></div>\n<div class=\"labstep\"><div>STEP 3 · Scale down — the claims stay behind</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl scale sts web --replicas=1\n<span class=\"p\">$</span> kubectl get pvc  <span class=\"g\"># data-web-1 STILL BOUND — retained by design (CH 10)</span></div></div>\n<p><b>Teardown:</b> <code>kubectl delete sts web &amp;&amp; kubectl delete svc web &amp;&amp; kubectl delete pvc data-web-0 data-web-1</code> — the PVCs <b>never</b> go with the STS.</p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#lab3\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#lab4\">next ▶</a></span><span>Page 17</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 4</span><h2 id=\"the-data-survival-gauntlet\">🧪 The Data-Survival Gauntlet</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\n<p>One claim, three disasters. Which data survives? Run each round and predict <i>before</i> looking:</p>\n<div class=\"labstep\"><div>SETUP · Claim + writer (reuse Lab 1's PV or Lab 2's dynamic claim)</div>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl run g1 --image=busybox:1.36 --restart=Never -- \\\n  sh -c <span class=\"m\">'echo round-one &gt; /data/state.txt; sleep 9999'</span>\n<span class=\"p\">$</span> kubectl patch pod g1 <span class=\"y\">--type</span>=merge <span class=\"y\">-p</span> \\\n  <span class=\"m\">'{\"spec\":{\"volumes\":[{\"name\":\"d\",\"persistentVolumeClaim\":{\"claimName\":\"surv\"}}]}}'</span> 2&gt;/dev/null \\\n  || kubectl run g1 --image=busybox:1.36 --restart=Never \\\n  --overrides=<span class=\"m\">'{\"spec\":{\"containers\":[{\"name\":\"g\",\"image\":\"busybox:1.36\",\n  \"command\":[\"sh\",\"-c\",\"echo round-one &gt; /data/state.txt; sleep 9999\"],\n  \"volumeMounts\":[{\"name\":\"d\",\"mountPath\":\"/data\"}]}],\n  \"volumes\":[{\"name\":\"d\",\"persistentVolumeClaim\":{\"claimName\":\"surv\"}}]}}'</span></div></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Round</th><th>Disaster</th><th>Prediction</th><th>Verdict</th></tr>\n<tr><td><b>1</b></td><td><code>kubectl delete pod g1</code></td><td>data…?</td><td><span class=\"ok\">SURVIVES</span> — it lives in the PV, not the Pod (Lab 3 proved the pattern)</td></tr>\n<tr><td><b>2</b></td><td><code>kubectl delete pvc surv</code> — while a Pod uses it</td><td>instant gone?</td><td><span class=\"stbadge st-term\">Terminating…</span> hangs — the <b>pvc-protection finalizer</b> (CH 06). Delete the Pod first, then it proceeds</td></tr>\n<tr><td><b>3</b></td><td>PVC gone + PV policy…</td><td>data…?</td><td><b>Retain</b> → <span class=\"stbadge st-comp\">Released</span>, bytes intact on the node (<code>minikube ssh ls /data/…</code>) · <b>Delete</b> → <span class=\"bad\">erased with the disk</span></td></tr>\n</table></div>\n<div class=\"term mini\"><span class=\"g\"># the one-liner verdict after every round:</span>\n<span class=\"p\">$</span> kubectl run chk --rm -it --image=busybox:1.36 --restart=Never \\\n  --overrides=<span class=\"m\">'{\"spec\":{\"containers\":[{\"name\":\"c\",\"image\":\"busybox:1.36\",\n  \"command\":[\"cat\",\"/data/state.txt\"],\n  \"volumeMounts\":[{\"name\":\"d\",\"mountPath\":\"/data\"}]}],\n  \"volumes\":[{\"name\":\"d\",\"persistentVolumeClaim\":{\"claimName\":\"surv\"}}]}}'</span></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The gauntlet's law:</b> data survives <b>Pod death</b> (always, once it's on a PVC), survives <b>slowly</b> through PVC death (finalizer + policy), and survives <b>PV death only under Retain</b>. Every storage SRE story is one of these three rounds.</div></div>\n<p><b>Teardown:</b> <code>kubectl delete pod g1 chk --ignore-not-found; kubectl delete pvc surv; kubectl delete pv pv-manual-1 --ignore-not-found</code></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#lab3\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#quiz\">quiz ▶</a></span><span>Page 17</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">QUIZ</span><h2 id=\"self-check-quiz\">✅ Self-Check Quiz</h2><span class=\"dbadge\">☑ 10 questions</span></div>\n<div class=\"qz\"><span class=\"qn\">Q1.</span>A container crashes and is restarted inside its Pod. Data written to an <code>emptyDir</code> volume…<br /><b>A.</b> survives — emptyDir lives with the Pod   <b>B.</b> is lost with the container layer   <b>C.</b> moves to another node   <b>D.</b> becomes read-only</div>\n<div class=\"qz\"><span class=\"qn\">Q2.</span>Which object is <b>cluster-scoped</b>?<br /><b>A.</b> PersistentVolumeClaim   <b>B.</b> StatefulSet   <b>C.</b> PersistentVolume   <b>D.</b> Service</div>\n<div class=\"qz\"><span class=\"qn\">Q3.</span><code>ReadWriteOnce</code> actually restricts mounting to…<br /><b>A.</b> one Pod   <b>B.</b> one NODE (any number of its Pods may share)   <b>C.</b> one container   <b>D.</b> one namespace</div>\n<div class=\"qz\"><span class=\"qn\">Q4.</span>Which is <b>NOT</b> a criterion the PV controller uses to match a claim?<br /><b>A.</b> capacity ≥ request   <b>B.</b> access modes ⊇ requested   <b>C.</b> storageClassName equality   <b>D.</b> the claiming Pod's name</div>\n<div class=\"qz\"><span class=\"qn\">Q5.</span>Retain policy, PVC deleted. The PV…<br /><b>A.</b> enters <b>Released</b> — data kept until an admin intervenes   <b>B.</b> is deleted with its backing disk   <b>C.</b> immediately becomes Available for reuse   <b>D.</b> enters Failed</div>\n<div class=\"qz\"><span class=\"qn\">Q6.</span>A PVC omits <code>storageClassName</code>; a default class exists. Result?<br /><b>A.</b> Pending until a manual PV matches   <b>B.</b> validation error   <b>C.</b> dynamically provisioned from the default class   <b>D.</b> binds only PVs labeled default</div>\n<div class=\"qz\"><span class=\"qn\">Q7.</span><code>volumeBindingMode: WaitForFirstConsumer</code> exists to…<br /><b>A.</b> slow down provisioning for safety   <b>B.</b> delay binding until a consuming Pod is scheduled — so zoned disks are born in the right zone   <b>C.</b> require admin approval   <b>D.</b> apply only to RWX volumes</div>\n<div class=\"qz\"><span class=\"qn\">Q8.</span>A StatefulSet scales 3 → 2 replicas. The removed replica's PVC…<br /><b>A.</b> is deleted immediately   <b>B.</b> is renamed   <b>C.</b> is transferred to a surviving replica   <b>D.</b> is retained by default — delete it manually if truly unwanted</div>\n<div class=\"qz\"><span class=\"qn\">Q9.</span><code>volumeClaimTemplates</code> means…<br /><b>A.</b> all replicas share one claim   <b>B.</b> admins must pre-create one PVC per replica   <b>C.</b> each replica gets its own PVC stamped from the template, named after its Pod   <b>D.</b> claims are optional</div>\n<div class=\"qz\"><span class=\"qn\">Q10.</span>CSI's core achievement is…<br /><b>A.</b> storage drivers hard-coded in the k8s tree   <b>B.</b> vendors ship storage drivers as out-of-tree containers against a standard interface   <b>C.</b> eliminating PVs entirely   <b>D.</b> automatic encryption of all volumes</div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#lab4\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#key\">answers ▶</a></span><span>Page 18</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">KEY</span><h2 id=\"answer-key-scoring\">🗝️ Answer Key + Scoring</h2><span class=\"dbadge\">grade yourself</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Q</th><th>Ans</th><th>Why — one line</th></tr>\n<tr><td>1</td><td><b>A</b></td><td>emptyDir outlives containers, dies with the Pod — the whole three-lives ladder (CH 01–02)</td></tr>\n<tr><td>2</td><td><b>C</b></td><td>PV = supply = cluster-wide; PVC/StatefulSet/Service are namespaced — Book 01 · CH 11 (CH 03)</td></tr>\n<tr><td>3</td><td><b>B</b></td><td>The unit is NODES — same-node Pods may share one RWO volume (CH 05)</td></tr>\n<tr><td>4</td><td><b>D</b></td><td>Pod names never enter matching: capacity, modes, class, selector only (CH 04)</td></tr>\n<tr><td>5</td><td><b>A</b></td><td>Retain = Released, data hostage; clearing claimRef re-opens it (CH 06)</td></tr>\n<tr><td>6</td><td><b>C</b></td><td>Omitted field + default class = dynamic provisioning; \"\" would opt out (CH 07)</td></tr>\n<tr><td>7</td><td><b>B</b></td><td>Wait for the consumer → disk born in the Pod's zone; fixes node-affinity conflict wedges (CH 08)</td></tr>\n<tr><td>8</td><td><b>D</b></td><td>Data-safety by design: claims outlive scaled-down replicas (CH 10, Lab 3)</td></tr>\n<tr><td>9</td><td><b>C</b></td><td>Template = cookie cutter: data-&lt;sts&gt;-&lt;ordinal&gt; per replica (CH 10)</td></tr>\n<tr><td>10</td><td><b>B</b></td><td>Standard interface + installable driver containers; in-tree frozen (CH 11)</td></tr>\n</table></div>\n<div class=\"grid3\">\n<div class=\"card center\"><div>🏆</div><p><b>9–10</b><br />Ready for Book 06</p></div>\n<div class=\"card center\"><div>📖</div><p><b>6–8</b><br />Re-read missed chapters' 🔑 boxes</p></div>\n<div class=\"card center\"><div>🔁</div><p><b>&lt;6</b><br />Re-run Labs 1–4, then retake</p></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Missed Q3?</b> The RWO-is-a-node lie is the most common storage misconception in interviews — drill it. Missed Q8 or Q9? StatefulSet storage behavior (claims outlive scale-down) is exactly what \"stateful\" <i>means</i>.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#quiz\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#gloss\">next ▶</a></span><span>Page 19</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">GLOSS</span><h2 id=\"glossary\">📚 Glossary</h2><span class=\"dbadge\">🔵 REFERENCE</span></div>\n<div class=\"gl\"><b>Volume</b> — a Pod-level directory mounted into containers; lifespan set by its type (emptyDir, hostPath, configMap, PVC…).</div>\n<div class=\"gl\"><b>emptyDir</b> — scratch volume sharing the Pod's life; survives container restarts, dies with the Pod; optional sizeLimit.</div>\n<div class=\"gl\"><b>hostPath</b> — node-local path; couples Pods to nodes and can expose the whole filesystem — daemon-only territory.</div>\n<div class=\"gl\"><b>PersistentVolume (PV)</b> — cluster-scoped piece of real storage with capacity, accessModes, reclaimPolicy; the supply.</div>\n<div class=\"gl\"><b>PersistentVolumeClaim (PVC)</b> — namespaced request (capacity + modes + class + selector); the only thing Pods mount.</div>\n<div class=\"gl\"><b>Binding</b> — 1:1 PV↔PVC match: capacity ≥, modes ⊇, class ==, selector match; smallest fitting PV wins.</div>\n<div class=\"gl\"><b>Access modes</b> — RWO (one NODE!), ROX, RWX (many nodes, shared filesystem), RWOP (one Pod, GA 1.29).</div>\n<div class=\"gl\"><b>Multi-Attach error</b> — a block volume refusing simultaneous attach to two nodes; the RWO-wedge signature.</div>\n<div class=\"gl\"><b>PV phases</b> — Available → Bound → Released (Retain holds here) → Failed; Released never auto-rebinds.</div>\n<div class=\"gl\"><b>Reclaim policy</b> — Retain (keep data, admin intervenes) / Delete (PV + backing storage destroyed; dynamic default) / Recycle (removed).</div>\n<div class=\"gl\"><b>pvc-protection finalizer</b> — keeps a PVC Terminating while a Pod still uses it.</div>\n<div class=\"gl\"><b>StorageClass</b> — named provisioning recipe: provisioner + parameters + reclaimPolicy + bindingMode + expansion flag.</div>\n<div class=\"gl\"><b>Dynamic provisioning</b> — claim names a class → provisioner builds storage + PV automatically; default class serves omitted fields; \"\" opts out.</div>\n<div class=\"gl\"><b>volumeBindingMode</b> — Immediate (bind now) vs WaitForFirstConsumer (bind when a Pod schedules — zone-correct).</div>\n<div class=\"gl\"><b>allowVolumeExpansion</b> — permits PVC growth (never shrink); filesystem resize online.</div>\n<div class=\"gl\"><b>StatefulSet</b> — workload controller giving replicas stable names (web-0…), per-Pod DNS via a headless Service, and ordered lifecycle.</div>\n<div class=\"gl\"><b>Headless Service</b> — clusterIP: None; DNS resolves each Pod individually — how followers find the primary by name.</div>\n<div class=\"gl\"><b>volumeClaimTemplates</b> — per-replica claim cookie-cutter: data-&lt;sts&gt;-&lt;ordinal&gt;; born on scale-up, retained on scale-down and on STS deletion.</div>\n<div class=\"gl\"><b>CSI</b> — Container Storage Interface: standard gRPC contract; drivers ship as controller (Deployment) + node (DaemonSet) plugins, out-of-tree.</div>\n<div class=\"gl\"><b>volumeMode</b> — Filesystem (formatted dir, default) vs Block (raw device passed to the Pod).</div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#key\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#cheat\">next ▶</a></span><span>Page 20</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CHEAT</span><h2 id=\"one-page-cheat-sheet\">📄 One-Page Cheat Sheet</h2><span class=\"dbadge\">🔵 print me</span></div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">💾 Storage — commands</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl get pv,pvc,sc\n<span class=\"p\">$</span> kubectl get pvc  <span class=\"g\"># Pending? check 4 match rules</span>\n<span class=\"p\">$</span> kubectl describe pv X  <span class=\"g\"># node affinity = its zone</span>\n<span class=\"p\">$</span> kubectl patch pv X -p \\\n  '{\"spec\":{\"persistentVolumeReclaimPolicy\":\"Retain\"}}'\n<span class=\"p\">$</span> kubectl patch pv X -p '{\"spec\":{\"claimRef\":null}}'<span class=\"g\"> # Released→Available</span>\n<span class=\"p\">$</span> kubectl patch pvc P -p \\\n  '{\"spec\":{\"resources\":{\"requests\":{\"storage\":\"10Gi\"}}}}'<span class=\"g\"> # grow only</span></div></div>\n<div class=\"card\"><div class=\"zlabel\">🏭 Production StorageClass</div><div class=\"term mini\"><span class=\"c\">provisioner</span>: ebs.csi.aws.com\n<span class=\"c\">parameters</span>: {type: gp3}\n<span class=\"c\">reclaimPolicy</span>: <span class=\"y\">Retain</span>  <span class=\"g\"># not Delete!</span>\n<span class=\"c\">allowVolumeExpansion</span>: <span class=\"y\">true</span>\n<span class=\"c\">volumeBindingMode</span>: <span class=\"y\">WaitForFirstConsumer</span>\n<span class=\"g\"># default class annotation:\nstorageclass.kubernetes.io/is-default-class: \"true\"</span></div></div>\n</div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">🪪 StatefulSet storage skeleton</div><div class=\"term mini\"><span class=\"c\">serviceName</span>: db  <span class=\"g\"># headless: clusterIP None</span>\n<span class=\"c\">volumeClaimTemplates</span>:\n- <span class=\"c\">metadata</span>: {name: data}\n  <span class=\"c\">spec</span>: {accessModes: [ReadWriteOnce],\n         resources: {requests: {storage: 10Gi}}}\n<span class=\"g\"># → data-db-0, data-db-1 …\n# scale-up: born · scale-down: RETAINED\n# delete STS: claims survive — manual cleanup</span></div></div>\n<div class=\"card\"><div class=\"zlabel\">🚑 Triage table</div><div class=\"table-scroll\"><table><tr><th>Symptom</th><th>Meaning</th></tr><tr><td>PVC Pending</td><td>class/capacity/mode/selector mismatch</td></tr><tr><td>Pod Pending + node affinity conflict</td><td>disk in wrong zone → WaitForFirstConsumer</td></tr><tr><td>Multi-Attach error</td><td>RWO volume wanted on 2 nodes</td></tr><tr><td>PVC Terminating forever</td><td>pvc-protection: Pod still using it</td></tr><tr><td>PV Released</td><td>Retain after claim death — admin's move</td></tr></table></div></div>\n</div>\n<div class=\"card\"><div class=\"zlabel\">🧠 Facts worth a job offer</div>\n<ul>\n<li>Three lives of data: container layer (dies with container) → emptyDir (dies with Pod) → PV (outlives everything)</li>\n<li>PV = cluster-scoped supply · PVC = namespaced demand · Pods mount the claim, never the volume</li>\n<li>RWO = one NODE, not one Pod — same-node Pods share it; RWX needs shared backing (NFS/EFS/Ceph)</li>\n<li>Retain keeps Released data hostage; Delete (dynamic default) erases PV + disk — patch before you delete</li>\n<li>WaitForFirstConsumer = disks born in the Pod's zone; storage grows but never shrinks</li>\n<li>StatefulSet claims: one per replica, named after the Pod, kept on scale-down and STS deletion</li>\n<li>CSI = the universal plug: drivers are containers (Deployment + DaemonSet), out-of-tree, independent releases</li>\n</ul></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#gloss\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#finale\">finale ▶</a></span><span>Page 21</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">FINALE</span><h2 id=\"what-you-can-do-now\">🗺️ What You Can Do Now</h2><span class=\"dbadge\">🎓 Book 05 complete</span></div>\n<p>Book 01 built the machine, 02 dressed it, 03 connected it, 04 placed it — Book 05 gave it <b>memory that survives death</b>.</p>\n<div class=\"mtree\"><b>💾 STORAGE — fully mapped:</b>\n├── <u>Ladder</u>          <span class=\"g\">container layer → emptyDir → PV (three lives of data)</span>\n├── <u>PV / PVC</u>        <span class=\"g\">cluster supply ⇄ namespaced demand · 4-rule binding</span>\n├── <u>Access modes</u>    <span class=\"g\">RWO = one NODE · RWX needs shared backing</span>\n├── <u>Reclaim</u>         <span class=\"g\">Available→Bound→Released→{Retain | Delete}</span>\n├── <u>StorageClass</u>    <span class=\"g\">dynamic recipes · WaitForFirstConsumer · grow-only</span>\n├── <u>StatefulSets</u>    <span class=\"g\">identity + per-replica claims that outlive scale-down</span>\n└── <u>CSI</u>             <span class=\"g\">drivers as containers — the universal plug</span></div>\n<h3 id=\"you-can-now\">✅ You can now…</h3>\n<ul>\n<li>Trace any byte of cluster data through its three lives and say exactly which disaster erases it</li>\n<li>Bind claims by hand AND provision dynamically — and explain the four matching rules when a PVC goes Pending</li>\n<li>Decode RWO/RWX correctly, diagnose Multi-Attach wedges, and pick the right backing per workload</li>\n<li>Write production StorageClasses: Retain policy, zone-correct binding, grow-only expansion</li>\n<li>Run a StatefulSet knowing precisely which disks belong to which replica — and what survives scale-down</li>\n<li>Read any <code>provisioner: …csi…</code> line and know the whole machinery behind it</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🎓</span><div><b>Where to next — Book 06 · Higher-Level Workloads:</b> you've met Deployments and tasted StatefulSets — Book 06 completes the zoo: <b>DaemonSets</b> (one Pod per node — you've seen them skip drains!), <b>Jobs &amp; CronJobs</b> (run-to-completion), <b>StatefulSets in full</b> (rolling updates, partition canaries), and the autoscaling trio <b>HPA/VPA/Cluster Autoscaler</b>. Your workloads can persist — now they learn to run themselves.</div></div>\n<div class=\"center\">— End of Book 05 · 🎬 —</div>\n<div class=\"pgfoot\"><span>📘 Book 05 · Storage</span><span><a href=\"#cheat\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a></span><span>Page 22</span></div></div>\n\n\n","toc":[{"id":"storagepersistencefor-pods","text":"STORAGEPERSISTENCEFOR PODS","level":1},{"id":"contents-click-any-row","text":"Contents — click any row","level":2},{"id":"why-storage-is-different","text":"🕳️ Why Storage Is Different","level":2},{"id":"volumes-the-pod-s-attachments","text":"🎒 Volumes — The Pod's Attachments","level":2},{"id":"pv-amp-pvc-supply-meets-demand","text":"🤝 PV &amp; PVC — Supply Meets Demand","level":2},{"id":"the-binding-process","text":"🔗 The Binding Process","level":2},{"id":"access-modes-rwo-rox-rwx-decoded","text":"🔀 Access Modes — RWO·ROX·RWX Decoded","level":2},{"id":"reclaim-policies-amp-the-pv-lifecycle","text":"♻️ Reclaim Policies &amp; the PV Lifecycle","level":2},{"id":"storageclasses-build-on-demand","text":"🏭 StorageClasses — Build on Demand","level":2},{"id":"storageclasses-continued","text":"🏭 StorageClasses — continued","level":2},{"id":"class-tuning-binding-modes-amp-expansion","text":"⚙️ Class Tuning — Binding Modes &amp; Expansion","level":2},{"id":"volumebindingmode-when-to-bind","text":"⏱️ volumeBindingMode — WHEN to bind","level":3},{"id":"allowvolumeexpansion-grow-never-shrink","text":"📈 allowVolumeExpansion — grow, never shrink","level":3},{"id":"statefulsets-why-identity-matters","text":"🪪 StatefulSets — Why Identity Matters","level":2},{"id":"the-headless-service-per-pod-dns","text":"📮 The headless service — per-Pod DNS","level":3},{"id":"volumeclaimtemplates-storage-per-replica","text":"🗄️ volumeClaimTemplates — Storage Per Replica","level":2},{"id":"csi-the-universal-plug","text":"🔌 CSI — The Universal Plug","level":2},{"id":"manual-pv-pvc-binding","text":"🔬 Manual PV ↔ PVC Binding","level":2},{"id":"dynamic-provisioning-reclaim-proof","text":"🏭 Dynamic Provisioning + Reclaim Proof","level":2},{"id":"statefulset-identity-amp-per-replica-data","text":"🔬 StatefulSet — Identity &amp; Per-Replica Data","level":2},{"id":"statefulset-continued","text":"🔬 StatefulSet — continued","level":2},{"id":"the-data-survival-gauntlet","text":"🧪 The Data-Survival Gauntlet","level":2},{"id":"self-check-quiz","text":"✅ Self-Check Quiz","level":2},{"id":"answer-key-scoring","text":"🗝️ Answer Key + Scoring","level":2},{"id":"glossary","text":"📚 Glossary","level":2},{"id":"one-page-cheat-sheet","text":"📄 One-Page Cheat Sheet","level":2},{"id":"what-you-can-do-now","text":"🗺️ What You Can Do Now","level":2},{"id":"you-can-now","text":"✅ You can now…","level":3}],"words":6820,"assets":[]};